<?php $wpImage=static fn(array $post):?string=>$post['_embedded']['wp:featuredmedia'][0]['source_url']??null;$plain=static fn($value)=>html_entity_decode(strip_tags((string)$value),ENT_QUOTES|ENT_HTML5,'UTF-8');$blogName=(string)($company?->getAttribute('trade_name')?:config('app.name')); ?>
<main class="blog-page"><section class="blog-hero"><div><span class="blog-eyebrow">Conseils &amp; expertise</span><h1>Le blog de <?= e($blogName) ?></h1><p>Conseils pratiques, actualités et informations utiles autour de nos services.</p></div></section><section class="blog-list"><div class="blog-list-inner"><div class="blog-head"><div><span class="blog-eyebrow blue">Nos publications</span><h2>Les derniers articles</h2></div></div><?php if($posts): ?><div class="blog-grid"><?php foreach($posts as $post):$image=$wpImage($post); ?><article><a href="/blog/<?= e($post['slug']??'') ?>" class="blog-card-image"><?php if($image): ?><img src="<?= e($image) ?>" alt="<?= e($plain($post['title']['rendered']??'')) ?>" loading="lazy"><?php else: ?><span><?= e(mb_substr($blogName,0,1)) ?></span><?php endif; ?></a><div><time><?= e(isset($post['date'])?date('d/m/Y',strtotime((string)$post['date'])):'') ?></time><h2><a href="/blog/<?= e($post['slug']??'') ?>"><?= e($plain($post['title']['rendered']??'')) ?></a></h2><p><?= e($plain($post['excerpt']['rendered']??'')) ?></p><a class="blog-read" href="/blog/<?= e($post['slug']??'') ?>">Lire l’article →</a></div></article><?php endforeach; ?></div><?php else: ?><div class="blog-empty"><h2>Le blog arrive bientôt</h2><p><?= e($blogError?:'Aucun article publié pour le moment.') ?></p></div><?php endif; ?></div></section></main>
